{
  "name": "海洋光学光谱仪",
  "name_en": "Ocean Optics spectrometer",
  "manufacturer": "Ocean Optics",
  "description": "一类紧凑型实验室光谱仪，用于测量光强随波长的分布，常用于吸收、透射、反射、荧光和光源表征等光学实验。部分型号可带快门、内置光源、辐照度校准、热电制冷和电子存储等功能。",
  "description_en": "A family of compact laboratory spectrometers used to measure light intensity as a function of wavelength. They are commonly used for optical measurements such as absorption, transmission, reflection, fluorescence, and light-source characterization. Some models may include features such as a shutter, built-in light source, irradiance calibration, thermoelectric cooling, and onboard memory.",
  "tag_hints": [
    "optical spectroscopy",
    "fiber optic spectrometer",
    "wavelength-resolved measurement",
    "irradiance calibration",
    "TEC cooling",
    "light source control",
    "triggered acquisition"
  ],
  "actions": [
    {
      "action_name": "auto-has_spectrometer_feature",
      "description": "检查是否支持光谱仪功能",
      "description_en": "Check whether spectrometer functionality is supported"
    },
    {
      "action_name": "auto-has_shutter_feature",
      "description": "检查是否支持快门功能",
      "description_en": "Check whether shutter functionality is supported"
    },
    {
      "action_name": "auto-has_light_source_feature",
      "description": "检查是否支持光源功能",
      "description_en": "Check whether light source functionality is supported"
    },
    {
      "action_name": "auto-has_continuous_strobe_feature",
      "description": "检查是否支持连续频闪输出功能",
      "description_en": "Check whether continuous strobe output is supported"
    },
    {
      "action_name": "auto-has_eeprom_feature",
      "description": "检查是否支持 EEPROM 存储功能",
      "description_en": "Check whether EEPROM storage is supported"
    },
    {
      "action_name": "auto-has_irrad_calibration_feature",
      "description": "检查是否支持辐照度校准功能",
      "description_en": "Check whether irradiance calibration is supported"
    },
    {
      "action_name": "auto-has_irrad_collection_area",
      "description": "检查是否支持采集面积参数",
      "description_en": "Check whether irradiance collection area information is supported"
    },
    {
      "action_name": "auto-has_tec_feature",
      "description": "检查是否支持热电制冷功能",
      "description_en": "Check whether thermoelectric cooling is supported"
    },
    {
      "action_name": "auto-has_lamp_feature",
      "description": "检查是否支持灯源功能",
      "description_en": "Check whether lamp functionality is supported"
    },
    {
      "action_name": "auto-has_nonlinearity_coeffs_feature",
      "description": "检查是否支持非线性校正系数",
      "description_en": "Check whether nonlinearity correction coefficients are supported"
    },
    {
      "action_name": "auto-has_stray_light_feature",
      "description": "检查是否支持杂散光校正信息",
      "description_en": "Check whether stray-light correction information is supported"
    },
    {
      "action_name": "auto-open_spectrometer",
      "description": "打开光谱仪连接",
      "description_en": "Open the spectrometer connection"
    },
    {
      "action_name": "auto-close_spectrometer",
      "description": "关闭光谱仪连接",
      "description_en": "Close the spectrometer connection"
    },
    {
      "action_name": "auto-set_trigger_mode",
      "description": "设置触发模式",
      "description_en": "Set the trigger mode"
    },
    {
      "action_name": "auto-set_integration_time_microsec",
      "description": "设置积分时间（微秒）",
      "description_en": "Set the integration time in microseconds"
    },
    {
      "action_name": "auto-set_shutter_open",
      "description": "设置快门开闭状态",
      "description_en": "Set the shutter open/closed state"
    },
    {
      "action_name": "auto-read_irrad_calibration",
      "description": "读取辐照度校准数据",
      "description_en": "Read irradiance calibration data"
    },
    {
      "action_name": "auto-write_irrad_calibration",
      "description": "写入辐照度校准数据",
      "description_en": "Write irradiance calibration data"
    },
    {
      "action_name": "auto-read_irrad_collection_area",
      "description": "读取辐照度采集面积",
      "description_en": "Read the irradiance collection area"
    },
    {
      "action_name": "auto-write_irrad_collection_area",
      "description": "写入辐照度采集面积",
      "description_en": "Write the irradiance collection area"
    },
    {
      "action_name": "auto-set_light_source_enable",
      "description": "设置指定光源的启用状态",
      "description_en": "Enable or disable the specified light source"
    },
    {
      "action_name": "auto-set_light_source_intensity",
      "description": "设置指定光源的强度",
      "description_en": "Set the intensity of the specified light source"
    },
    {
      "action_name": "auto-read_eeprom_slot",
      "description": "读取指定 EEPROM 槽位数据",
      "description_en": "Read data from the specified EEPROM slot"
    },
    {
      "action_name": "auto-write_eeprom_slot",
      "description": "写入指定 EEPROM 槽位数据",
      "description_en": "Write data to the specified EEPROM slot"
    },
    {
      "action_name": "auto-read_tec_temperature",
      "description": "读取热电制冷温度",
      "description_en": "Read the thermoelectric cooler temperature"
    },
    {
      "action_name": "auto-set_tec_temperature",
      "description": "设置热电制冷目标温度",
      "description_en": "Set the thermoelectric cooler target temperature"
    },
    {
      "action_name": "auto-set_tec_enable",
      "description": "设置热电制冷启用状态",
      "description_en": "Enable or disable thermoelectric cooling"
    },
    {
      "action_name": "auto-set_tec_fan_enable",
      "description": "设置热电制冷风扇启用状态",
      "description_en": "Enable or disable the thermoelectric cooler fan"
    },
    {
      "action_name": "auto-set_continuous_strobe_period_microsec",
      "description": "设置连续频闪周期（微秒）",
      "description_en": "Set the continuous strobe period in microseconds"
    },
    {
      "action_name": "auto-get_model",
      "description": "获取型号",
      "description_en": "Get the model"
    },
    {
      "action_name": "auto-get_min_integration_time_microsec",
      "description": "获取最小积分时间（微秒）",
      "description_en": "Get the minimum integration time in microseconds"
    },
    {
      "action_name": "auto-get_unformatted_spectrum",
      "description": "获取未格式化光谱数据",
      "description_en": "Get the unformatted spectrum data"
    },
    {
      "action_name": "auto-get_formatted_spectrum",
      "description": "获取格式化光谱数据",
      "description_en": "Get the formatted spectrum data"
    },
    {
      "action_name": "auto-get_unformatted_spectrum_length",
      "description": "获取未格式化光谱长度",
      "description_en": "Get the unformatted spectrum length"
    },
    {
      "action_name": "auto-get_formatted_spectrum_length",
      "description": "获取格式化光谱长度",
      "description_en": "Get the formatted spectrum length"
    },
    {
      "action_name": "auto-get_wavelengths",
      "description": "获取波长轴",
      "description_en": "Get the wavelength axis"
    },
    {
      "action_name": "auto-get_electric_dark_pixel_indices",
      "description": "获取电子暗像素索引",
      "description_en": "Get the electric dark pixel indices"
    },
    {
      "action_name": "auto-get_light_source_count",
      "description": "获取光源数量",
      "description_en": "Get the number of light sources"
    },
    {
      "action_name": "auto-get_serial_number",
      "description": "获取序列号",
      "description_en": "Get the serial number"
    }
  ]
}

